<section class="account-settings-page grid gap-6">
    <x-feedback />
    <x-page-header title="Account settings" :eyebrow="auth()->user()->can('admin.access') ? 'Your workspace identity' : ''" description="Manage your password and keep your account secure." />
    <div class="grid items-start gap-6 lg:grid-cols-3"><aside class="surface account-profile-card p-6"><x-profile-photo-editor /><h2 class="mt-5 text-lg font-semibold">{{ auth()->user()->name }}</h2><p class="mt-2 break-all text-xs text-ink-500">{{ auth()->user()->email }}</p><div class="mt-6 flex items-start gap-3 border-t border-ink-100 pt-5"><x-icon name="shield" class="size-4" /><p class="text-[11px] leading-6 text-ink-500">Use a unique password. Never share your staff account or sign-in details.</p></div></aside>
    <form wire:submit="save" class="surface grid gap-5 p-6 sm:p-8 lg:col-span-2"><div class="border-b border-ink-100 pb-5"><h2 class="text-base font-semibold">Change password</h2><p class="mt-2 text-xs leading-6 text-ink-500">Confirm your current password before choosing a new one.</p></div><x-input name="current_password" label="Current password" type="password" wire:model="current_password" required autocomplete="current-password" /><x-input name="password" label="New password" type="password" wire:model="password" required minlength="12" autocomplete="new-password" help="At least 12 characters, mixed case letters, a number and a symbol." /><x-input name="password_confirmation" label="Confirm new password" type="password" wire:model="password_confirmation" required autocomplete="new-password" /><div class="flex flex-wrap items-center gap-4 border-t border-ink-100 pt-5"><x-button wire:loading.attr="disabled" wire:target="save"><x-icon name="lock" class="size-4" />Update password</x-button><span wire:loading wire:target="save" class="text-xs text-ink-500">Updating your password…</span></div></form></div>
</section>
